html:
{% set count_data = frappe.flags.inventory_count_data %}
<p style="font-size:100%;" class="text-center">
<img id="qr" width="66%" src="https://api.qrserver.com/v1/create-qr-code/?size=300x300&data={{ doc.name }}&format=svg&color=000000">
</p>
<p style="font-size:150%;" class="text-center">{{ doc.name }}</p>
<p style="font-size:100%;" class="text-center">{{ doc.item_name }}</p>
{% if count_data %}
<p style="font-size:200%;" class="text-center"><b>Gezählt: {{ count_data.counted_qty }}</b></p>
<p style="font-size:80%;" class="text-center">{{ count_data.counted_at }}</p>
{% endif %}
